sources.read:
[Module load: #time]; [Module load: #json];
[[|
let owner := Globals; [owner at: #globalsBenchValue put: 7];
let operation := [:count | [[1 to: count] inject: 0 into: [:sum :i | [sum + [owner at: #globalsBenchValue]]]]]; [operation value: 10]; [System gc];
let facts := [db retainedFactCount]; let cpu := [16 clockNanos];
let answer := [operation value: 2000]; let elapsed := [[16 clockNanos] - cpu];
[System gc];
[System println: [Json stringify: {"answer" -> answer "cpu_ns" -> elapsed "fact_delta" -> [[db retainedFactCount] - facts]}]]
] value]

